-- Frete > Carretas EMT: mapa das rotas das carretas, com produção, km e tempo por rota.
--
-- PEDIDO DO TIAGO (01/10/2026): "no final dessa aba quero uma imagem do google maps mostrando a
-- producao de frete de cada uma das rotas que as carretas fazem [...] trace cada uma das rotas,
-- coloque os km da rota, producao por rota, tempo medio de cada rota baseado nas saidas e
-- chegadas de cada frete." Ele mandou o link do Maps de cada local.
--
-- ============================================================
-- 1. COORDENADA NA LOCALIDADE
-- ============================================================
-- Os sete locais que as carretas usam, pelos links que ele mandou (resolvidos em 01/10/2026). Os
-- três que já tinham link no endereço (Britam, Formate, Vale do Abunã) batem com estes a menos de
-- 300 m. NUMERIC(9,6): seis casas de grau são ~10 cm, e coordenada não é dinheiro nem taxa.
alter table public.localidades
  add column if not exists latitude numeric(9,6) check (latitude between -90 and 90),
  add column if not exists longitude numeric(9,6) check (longitude between -180 and 180);
-- Os grants de localidades são por coluna: coluna nova nasce sem privilégio nenhum.
grant select (latitude, longitude), insert (latitude, longitude), update (latitude, longitude)
  on public.localidades to authenticated;

update public.localidades l set latitude = v.lat, longitude = v.lng
from (values
    ('5081e972-827a-ebb9-f7e7-09af0ce7037b'::uuid, -7.620353, -72.698779),  -- Colorado
    ('66334343-b89b-5bbd-b39c-6d89cb2e0036'::uuid, -7.742554, -72.476503),  -- Patio Lote 10
    ('0a04b9e6-5216-548a-2d90-41a9c0ca88b7'::uuid, -7.952232, -71.491783),  -- Usina Gregorio
    ('180e1559-11a1-1ca9-38df-dfa528218911'::uuid, -7.854135, -71.786684),  -- Pulmão 1 KM657
    ('6c985511-fd06-1e49-0779-915f38194bfa'::uuid, -9.756564, -65.556838),  -- Pedreira Formate
    ('3cc79168-59e5-b8cc-22a9-6a3bea3d0ef5'::uuid, -9.818788, -66.216733),  -- Pedreira Britam
    ('7a49b138-53b1-80b6-398b-4246b4bfeadc'::uuid, -9.668667, -65.516889)   -- Vale do Abunã
) as v(id, lat, lng)
where l.id = v.id;

-- ============================================================
-- 2. O TRAÇADO DE CADA ROTA
-- ============================================================
-- O caminho pela estrada entre dois locais, calculado uma vez no OSRM (roteador sobre o
-- OpenStreetMap) e guardado aqui: a tela desenha a rota sem chamar serviço externo. Pontos
-- [lat, lng] simplificados (Douglas-Peucker, ~90 m), 19 a 135 por rota. km_mapa é a distância
-- pela estrada; o km do frete continua sendo o que se lança no frete, e a tela mostra os dois.
-- Rota nova sem traçado aparece no mapa como linha reta tracejada.
create table if not exists public.frete_rotas_tracado (
  origem_localidade_id uuid not null references public.localidades(id),
  destino_localidade_id uuid not null references public.localidades(id),
  km_mapa numeric(14,4) not null check (km_mapa >= 0),
  horas_mapa numeric(14,4) check (horas_mapa >= 0),
  tracado jsonb not null check (jsonb_typeof(tracado) = 'array'),
  fonte text not null default 'OSRM (OpenStreetMap)',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references public.usuarios(id),
  primary key (origem_localidade_id, destino_localidade_id)
);
create index if not exists idx_frete_rotas_tracado_destino on public.frete_rotas_tracado (destino_localidade_id);

alter table public.frete_rotas_tracado enable row level security;
create policy frete_rotas_tracado_select on public.frete_rotas_tracado
  for select to authenticated using ((select public.fn_ve_frete()));
grant select on public.frete_rotas_tracado to authenticated;
create trigger trg_audit_frete_rotas_tracado after insert or delete or update on public.frete_rotas_tracado
  for each row execute function public.fn_audit();

insert into public.frete_rotas_tracado (origem_localidade_id, destino_localidade_id, km_mapa, horas_mapa, tracado)
