    ('7a49b138-53b1-80b6-398b-4246b4bfeadc'::uuid, '0a04b9e6-5216-548a-2d90-41a9c0ca88b7'::uuid, 769.3, 11.6, '[[-9.6681,-65.5171],[-9.668,-65.5162],[-9.6669,-65.5177],[-9.6601,-65.5165],[-9.6464,-65.5989],[-9.6467,-65.6024],[-9.6513,-65.6136],[-9.658,-65.6492],[-9.6498,-65.6837],[-9.6473,-65.6996],[-9.6578,-65.7284],[-9.6633,-65.7843],[-9.6628,-65.7926],[-9.6671,-65.802],[-9.6671,-65.8307],[-9.6812,-65.8819],[-9.6867,-65.9813],[-9.7013,-66.0211],[-9.7167,-66.0997],[-9.7363,-66.1529],[-9.7664,-66.2993],[-9.7699,-66.3166],[-9.7713,-66.3604],[-9.7984,-66.5267],[-9.7978,-66.5303],[-9.7454,-66.629],[-9.7561,-66.7214],[-9.7641,-66.7699],[-9.7727,-66.8126],[-9.8362,-66.8921],[-9.8611,-66.9097],[-9.937,-66.9788],[-9.9379,-66.9822],[-9.9387,-67.0398],[-9.9848,-67.1654],[-9.9954,-67.1839],[-10.0276,-67.2509],[-10.041,-67.2671],[-10.0463,-67.2773],[-10.0542,-67.2858],[-10.062,-67.2979],[-10.0603,-67.3207],[-10.0617,-67.3465],[-10.1124,-67.4674],[-10.1128,-67.4724],[-10.0728,-67.5583],[-10.0725,-67.5613],[-10.0752,-67.5716],[-10.0743,-67.5752],[-10.0145,-67.6592],[-10.0114,-67.7985],[-10.0061,-67.8029],[-9.9985,-67.7997],[-9.9927,-67.8012],[-9.9791,-67.7966],[-9.9732,-67.7986],[-9.9677,-67.831],[-9.9606,-67.851],[-9.9604,-67.8566],[-9.9527,-67.8621],[-9.9354,-67.8829],[-9.9319,-67.8852],[-9.8975,-67.8934],[-9.8476,-67.9264],[-9.6995,-68.1663],[-9.3876,-68.4483],[-9.2489,-68.508],[-9.0874,-68.6297],[-9.0756,-68.6912],[-9.0707,-68.73],[-9.0641,-68.7432],[-9.0597,-68.7476],[-9.0586,-68.752],[-9.0122,-68.8272],[-8.9381,-69.1949],[-8.8749,-69.2978],[-8.835,-69.3236],[-8.7036,-69.5695],[-8.6208,-69.7331],[-8.5925,-69.812],[-8.4767,-70.1512],[-8.4733,-70.1547],[-8.432,-70.1747],[-8.4155,-70.1782],[-8.2508,-70.2964],[-8.2169,-70.3285],[-8.1887,-70.3487],[-8.1757,-70.3732],[-8.1716,-70.3774],[-8.1703,-70.3832],[-8.1588,-70.4048],[-8.1593,-70.4442],[-8.1928,-70.5279],[-8.1853,-70.6166],[-8.1685,-70.6867],[-8.1683,-70.7002],[-8.1588,-70.7228],[-8.1518,-70.729],[-8.1516,-70.7539],[-8.1413,-70.7667],[-8.1424,-70.7721],[-8.1418,-70.7851],[-8.1333,-70.8842],[-8.1317,-70.8891],[-8.1325,-70.8945],[-8.1313,-70.9184],[-8.1283,-70.9292],[-8.129,-70.9345],[-8.1222,-71.016],[-8.0857,-71.0898],[-8.0744,-71.1729],[-8.0594,-71.2014],[-8.0575,-71.2474],[-8.0551,-71.2588],[-8.0473,-71.2816],[-8.0471,-71.2899],[-8.044,-71.2944],[-8.0396,-71.3061],[-8.0067,-71.3565],[-8.0049,-71.3608],[-7.9921,-71.379],[-7.9566,-71.4667],[-7.9522,-71.4918]]'::jsonb)
